import java.security.*;import java.util.*;import java.nio.charset.*;
public class CreatingDigitalSignature{public static void main(String[]x)throws Exception{Scanner s=new Scanner(System.in);System.out.print("Enter some text: ");String m=s.nextLine();KeyPairGenerator g=KeyPairGenerator.getInstance("DSA");g.initialize(2048);KeyPair p=g.generateKeyPair();Signature z=Signature.getInstance("SHA256withDSA");z.initSign(p.getPrivate());z.update(m.getBytes(StandardCharsets.UTF_8));byte[]sig=z.sign();System.out.println("Digital signature (Base64): "+Base64.getEncoder().encodeToString(sig));z.initVerify(p.getPublic());z.update(m.getBytes(StandardCharsets.UTF_8));System.out.println("Signature verified: "+z.verify(sig));}}
